import ast,hashlib,json
from pathlib import Path
patches=[{'path': '/app/run.py', 'function': '_authoritative_exit_code', 'before_sha256': 'b4c96ab2f862156493a9914248b8527ce14b07b26ace88c6ccd7130a597ee294', 'after': 'def _authoritative_exit_code(path=None):\n    # save_final_results writes common_design_envelope.json; older builds\n    # wrote final_results.json. Read whichever exists so the exit code\n    # reflects the REAL status (a missing file must never read as success).\n    _candidates = ([path] if path else\n                   ["/output/common_design_envelope.json", "/output/final_results.json"])\n    for _p in _candidates:\n        try:\n            with open(_p, encoding="utf-8") as stream:\n                result = json.load(stream)\n            code = 0 if (result.get("status") == "completed" and\n                         result.get("validation", {}).get("verdict") in\n                         ("pass", "pass_with_caveats", "review")) else 1\n            if code:\n                print("CDE_JSON=" + json.dumps(result, separators=(",", ":")), flush=True)\n            return code\n        except Exception:\n            continue\n    return 1'}, {'path': '/app/dft_utils.py', 'function': '_classify_scan_cells', 'before_sha256': 'c4a176843b15758f06c853aeb78e498036f37001e99984e44bb8765b106bac6b', 'after': 'def _classify_scan_cells(cells):\n    scannable = 0\n    hazards = {"latch": 0, "async_set_reset": 0, "gated_or_other": 0}\n    for cell in cells.values():\n        cell_type = str(cell.get("type", ""))\n        if not cell_type.startswith("$"):\n            lower = cell_type.lower()\n            if re.search(r"(?:^|__)[a-z]*dl[a-z]*tp", lower) or "latch" in lower:\n                hazards["latch"] += 1\n            elif re.search(r"(?:^|__)[a-z]*df[a-z]*[rs][a-z]*tp", lower) \\\n                    or re.search(r"__s?edf|__dffs|__sdf[bf]", lower):\n                hazards["async_set_reset"] += 1\n            elif re.search(r"(?:^|__)[a-z]*df[a-z]*tp", lower) \\\n                    or "__dff" in lower:\n                scannable += 1\n            continue\n        upper = cell_type.upper()\n        # Yosys proc retains vector registers as one cell; scan chains shift\n        # storage bits, not vector-cell instances.\n        width = max(1, len(cell.get("connections", {}).get("Q", [])))\n        if upper.startswith(("$DLATCH", "$_DLATCH")):\n            hazards["latch"] += width\n        elif upper.startswith(("$ADFF", "$ALDFF", "$DFFSR", "$SDFFCE",\n                               "$_DFFSR", "$_SDFF", "$_ADFF")):\n            hazards["async_set_reset"] += width\n        elif upper.startswith(("$DFF", "$DFFE", "$SDFF", "$_DFF")):\n            scannable += width\n        elif upper.startswith("$DLATCHSR"):\n            hazards["gated_or_other"] += width\n    total = scannable + sum(hazards.values())\n    coverage = round(100.0 * scannable / total, 2) if total else 0.0\n    return {\n        "scannable_ff": scannable, "hazards": hazards,\n        "total_sequential": total, "coverage_estimate_pct": coverage,\n        "clean": scannable > 0 and not any(hazards.values()),\n    }'}]
for patch in patches:
 p=Path(patch['path']); source=p.read_text(); tree=ast.parse(source)
 n=next(n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name==patch['function'])
 old=ast.get_source_segment(source,n)
 if old==patch['after']: continue
 if hashlib.sha256(old.encode()).hexdigest()!=patch['before_sha256']: raise RuntimeError('qualification39 source precondition mismatch: '+patch['path']+':'+patch['function'])
 lines=source.splitlines(keepends=True)
 p.write_text(''.join(lines[:n.lineno-1])+patch['after']+'\n'+''.join(lines[n.end_lineno:]))
 print('QUALIFICATION39_PATCH='+patch['path']+':'+patch['function'],flush=True)
